import {MAPS,visibleObjects,nearObject} from './world.js';
const imgs={};function img(name){if(!imgs[name]){const i=new Image();i.src='assets/gm/'+name+'.png';imgs[name]=i;}return imgs[name];}
const beeAtlas=new Image();beeAtlas.src='assets/bees-v6.png';
const accents=['#76d7cd','#a4cf7c','#c39ee3','#efc777'];
export function drawWorld(canvas,s,time,dir=0,walking=false){const c=canvas.getContext('2d');c.imageSmoothingEnabled=false;const m=MAPS[s.map],w=480,h=270;const ox=Math.round(Math.max(0,Math.min(m.w-w,s.x-w/2))),oy=Math.round(Math.max(0,Math.min(m.h-h,s.y-h/2)));c.fillStyle='#111a29';c.fillRect(0,0,w,h);c.save();c.translate(-ox,-oy);
const rect=(x,y,w,h,col)=>{c.fillStyle=col;c.fillRect(Math.round(x),Math.round(y),w,h);};const text=(t,x,y,col='#f3e2b8')=>{c.font='8px monospace';c.fillStyle=col;c.textAlign='center';c.fillText(t,x,y);};
const outdoors=m.floor==='grass',garden=m.floor==='garden',metal=['lab','ship','stone'].includes(m.floor);let base=outdoors?'#53684b':garden?'#8b9169':metal?'#526172':'#887358';
rect(0,0,m.w,m.h,base);for(let y=0;y<m.h;y+=16)for(let x=0;x<m.w;x+=16){const seed=(x*7+y*13)%47;if(outdoors){rect(x+seed%12,y+seed%11,2,2,seed%2?'#667d54':'#465e46');if(seed<4)rect(x+3,y+8,3,2,'#9aab6a');}else{rect(x,y,16,1,metal?'#657385':'#a38b68');rect(x,y,1,16,metal?'#435261':'#776346');if(!metal)rect(x+3,y+7,9,1,'#8e795a');}}
if(outdoors){for(const [x,y,ww,hh] of [[108,130,38,300],[108,180,610,34],[370,130,30,280],[620,180,34,260]]){rect(x,y,ww,hh,'#b8a582');for(let k=0;k<ww*hh/300;k++)rect(x+(k*31)%ww,y+(k*19)%hh,3,2,'#a59575');}rect(266,266,14,95,'#89735c');rect(532,266,14,95,'#89735c');}
else{rect(0,0,m.w,38,'#28374b');rect(0,37,m.w,5,'#baa076');rect(0,0,16,m.h,'#243447');rect(m.w-16,0,16,m.h,'#243447');rect(16,m.h-9,m.w-32,9,'#243447');for(let x=40;x<m.w-40;x+=96){rect(x,8,48,25,'#8faeb0');rect(x+3,10,42,20,s.map==='ship'?'#122444':'#adc5b7');rect(x+23,8,3,25,'#4b665f');if(s.map==='ship'){rect(x+7,16,2,2,'#e8c778');rect(x+34,23,1,1,'#d3dee0');}}if(s.map==='home'){rect(190,135,100,75,'#6c6376');rect(194,139,92,67,'#918694');rect(198,143,84,59,'#7f7485');}if(s.map==='lab'){rect(184,145,112,74,'#8c887e');rect(188,149,104,66,'#a8a080');}if(s.map==='ship'){rect(214,41,52,9,'#ba9764');rect(216,43,48,5,'#76a9be');}}
function character(x,y,role,frame=0){rect(x-7,y-3,14,4,'#17233155');const im=img('spr_crew-'+frame);if(im.complete&&im.naturalWidth)c.drawImage(im,Math.round(x-14),Math.round(y-29),28,28);const a=accents[role];if(role===0){rect(x-7,y-21,14,3,a);rect(x-6,y-20,4,3,'#366275');rect(x+2,y-20,4,3,'#366275');}else if(role===1){rect(x,y-33,2,6,'#567e51');rect(x-3,y-34,4,3,a);rect(x+2,y-36,4,3,a);}else if(role===2){rect(x-11,y-22,3,10,a);rect(x+8,y-22,3,10,a);}else{rect(x-5,y-12,10,3,a);rect(x+3,y-9,3,6,a);}}
function object(o){const {x,y,w,h,kind}=o;rect(x+3,y+h-3,w,6,'#14253133');switch(kind){
case 'house':{const col=o.id==='home'?'#a07970':o.id==='garden'?'#73947c':o.id==='lab'?'#788b9c':'#8c7f96';rect(x,y+20,w,h-20,col);rect(x-5,y+15,w+10,14,'#3c465c');rect(x+5,y+3,w-10,15,'#58627a');rect(x+14,y,w-28,5,'#6b758b');for(let ry=5;ry<26;ry+=6)for(let rx=9;rx<w-12;rx+=13)rect(x+rx,y+ry,11,1,'#879097');for(let k=14;k<w-20;k+=30){rect(x+k,y+35,18,23,'#354453');rect(x+k+2,y+37,14,18,s.flags.radioFixed||o.id==='home'?'#eacb82':'#8ea9ac');rect(x+k+9,y+36,2,21,'#516170');}rect(x+w/2-10,y+h-29,20,29,'#283947');rect(x+w/2-8,y+h-27,16,27,'#637476');rect(x+w/2+4,y+h-15,2,2,'#e8cf8a');rect(x+8,y+23,w-16,10,'#233448');text(o.label[s.lang==='es'?0:1],x+w/2,y+31);break;}
case 'tree':rect(x+12,y+10,10,h,'#796651');rect(x+4,y,28,32,'#354e43');rect(x-4,y-8,44,25,'#3d5c48');rect(x+3,y-18,31,25,'#587151');rect(x+9,y-19,15,4,'#75885a');break;
case 'pond':rect(x,y,w,h,'#7c997d');rect(x+5,y+4,w-10,h-8,'#527984');rect(x+10,y+8,w-20,h-16,'#426879');for(let k=0;k<9;k++)rect(x+12+(k*13)%80,y+15+(k*19)%45,12,1,'#749ca2');break;
case 'bed':rect(x,y,w,h,'#5b4c48');rect(x+4,y+3,w-8,15,'#d7d6bd');rect(x+4,y+19,w-8,h-24,'#6e8291');rect(x+7,y+22,w-14,3,'#9cb7ba');break;
case 'desk':case 'table':case 'bench':rect(x+3,y+h-4,5,10,'#4c4a42');rect(x+w-8,y+h-4,5,10,'#4c4a42');rect(x,y,w,h,'#5d584d');rect(x+2,y+2,w-4,h-8,'#b29a71');rect(x+3,y+3,w-6,2,'#d1b789');if(o.id==='desk'){rect(x+62,y+9,9,11,'#b2c0b3');rect(x+69,y+11,5,6,'#748d8d');rect(x+63,y+8,7,2,'#544a44');rect(x+66,y+3-Math.floor(time/500)%3,2,4,'#b2c0b388');rect(x+5,y+5,11,8,'#ca9a86');rect(x+7,y+7,7,1,'#894f54');rect(x+39,y+7,11,8,'#cfb3a0');rect(x+41,y+9,7,1,'#a45b5b');}if(o.id==='desk'&&s.flags.notebookPlaced){rect(x+18,y+12,15,12,'#384c62');rect(x+20,y+13,11,9,'#d2d1af');}if(o.id==='review'){for(let k=0;k<4;k++)rect(x+8+k*13,y+9,8,8,k<s.friends.length+1?'#e6ce92':'#8b8068');}break;
case 'box':rect(x,y,w,h,'#695b4a');rect(x+2,y+2,w-4,h-6,'#b69a70');rect(x-4,y-4,15,8,'#d1b383');rect(x+17,y-4,15,8,'#c7a678');rect(x+8,y+5,12,10,s.carry||s.flags.notebookPlaced?'#594f46':'#40566b');break;
case 'plant':rect(x+4,y+12,16,13,'#a77561');rect(x+3,y+11,18,3,'#c39c78');rect(x+11,y-4,3,18,'#6b8d57');rect(x+3,y,10,5,s.flags.plantWatered?'#9dbf75':'#88785d');rect(x+13,y-5,9,5,s.flags.plantWatered?'#9dbf75':'#88785d');break;
case 'flowers':rect(x,y,w,h,'#5a5645');for(let k=0;k<8;k++){let xx=x+9+(k%4)*23,yy=y+9+Math.floor(k/4)*21;rect(xx,yy,2,14,'#75955b');if(s.flags.flowersWatered||s.map==='mars'&&s.flags.bloom){rect(xx-3,yy-2,8,5,'#d7ad88');rect(xx,yy-4,2,9,'#e5c68c');rect(xx,yy,2,2,'#ebdd9f');}else rect(xx-2,yy+5,6,2,'#8f9971');}break;
case 'hive':rect(x,y,w,h,'#38546a');rect(x+3,y+3,w-6,h-6,'#88b9ba');rect(x+6,y+6,w-12,h-12,'#b4c7b3');rect(x+3,y+h-9,w-6,6,'#607b83');{if(beeAtlas.complete&&beeAtlas.naturalWidth){const pose=s.mission.flight?.risk>35?2:s.map==='garden'?0:1;const cell=beeAtlas.naturalWidth/2;c.drawImage(beeAtlas,(pose%2)*cell,Math.floor(pose/2)*cell,cell,cell,x+w/2-20,y+1+Math.round(Math.sin(time/550)),40,40);}}rect(x+w-7,y+h-7,3,3,s.mission.flight?.risk>35?'#eea37d':'#a5d39c');break;
case 'console':case 'radio':case 'chart':rect(x,y,w,h,'#2b4054');rect(x+3,y+3,w-6,h-10,'#5a7f8c');rect(x+6,y+5,w-12,h-17,'#a9c5b5');if(kind==='chart'){for(let k=0;k<3;k++){rect(x+12+k*16,y+12+k*3,5,5,['#8bbaac','#ceab7b','#b98872'][k]);}rect(x+13,y+18,38,1,'#5b8190');}else{let active=o.id!=='radio'||s.radioOn&&s.radioFixed;rect(x+9,y+9,w-18,2,active?'#577d71':'#8a9590');for(let k=0;k<4;k++)rect(x+9+k*10,y+h-6,4,2,active?'#e7cc8a':'#798b8c');}break;
case 'switch':rect(x,y,w,h,'#34485a');rect(x+6,y+4,12,16,s.radioOn?'#ddc58d':'#7a8a9b');rect(x+8,y+(s.radioOn?6:14),8,4,'#cbd3c5');break;
case 'shelf':rect(x,y,w,h,'#574b46');rect(x+3,y+3,w-6,h-6,'#a38b66');for(let k=0;k<5;k++)rect(x+7+k*11,y+5,7,h-10,['#bdbc92','#788e91','#a87972'][k%3]);break;
case 'letter':rect(x,y,w,h,'#e4d6ae');rect(x+2,y+2,w-4,1,'#bea272');rect(x+5,y+5,5,3,'#b18069');break;
case 'door':rect(x,y,w,h,'#253b48');rect(x+2,y+2,w-4,h-2,'#b5aa87');rect(x+3,y+3,w-6,2,'#ead9aa');break;
case 'window':rect(x,y,w,h,'#839b9e');rect(x+3,y+3,w-6,h-6,'#182f4a');for(let k=0;k<6;k++)rect(x+6+k*8,y+8+k%3*5,1,1,'#ead5a0');break;
case 'npc':character(x+w/2,y+h,o.role);break;
}}
const objects=visibleObjects(s);let layers=[...objects.map(o=>({z:o.y+o.h,draw:()=>object(o)})),{z:s.y,draw:()=>character(Math.round(s.x),Math.round(s.y),3,dir*4+(walking?Math.floor(time/155)%4:0))}];layers.sort((a,b)=>a.z-b.z).forEach(l=>l.draw());
if(s.map==='lab'){s.friends.forEach((id,i)=>character(180+i*60,230,['Pip','Nim','Eko'].indexOf(id)));}if(s.map==='mars'&&s.flags.bloom){const im=img('spr_queen_calm-'+Math.floor(time/140)%4);if(im.complete&&im.naturalWidth)c.drawImage(im,220+Math.sin(time/1100)*18,130+Math.cos(time/900)*7,32,24);}
if(outdoors){for(let i=0;i<16;i++){let x=(time*.008+i*53)%m.w,y=50+(i*37)%480;rect(x,y,1,1,'#e9d59488');}}
const near=nearObject(s);if(near){const xx=near.x+near.w/2,yy=near.y-9+Math.sin(time/220)*2;rect(xx-5,yy,10,9,'#132a3a');text('E',xx,yy+7);}
if(s.map==='home'&&s.flags.finalKind){if(s.flags.finalKind==='bankrupt'){rect(35,160,112,40,'#887358');character(155,205,0);character(330,220,2);rect(200,250,80,16,'#812f42');text(s.lang==='es'?'CLAUSURADO':'CLOSED',240,261);}else{character(168,195,0);character(205,212,1);character(290,201,2);rect(355,84,16,8,'#ab4f48');rect(352,81+Math.sin(time/90),22,4,'#d2745b');}}
if(s.map==='home'&&!s.flags.grant){rect(0,0,m.w,m.h,'#1e274932');}c.restore();return {ox,oy};}
